import os
import json
from google.cloud import documentai_v1 as documentai

def process_expense_document(project_id: str, location: str, processor_id: str, file_path: str) -> dict:
    """
    Processes an expense document using Google Cloud Document AI and normalizes the output.

    Args:
        project_id: Your Google Cloud project ID.
        location: The location of the processor (e.g., "us").
        processor_id: The ID of the expense processor.
        file_path: The path to the document file (e.g., "receipt.pdf").

    Returns:
        A dictionary representing the normalized expense data.
    """
    client = documentai.DocumentProcessorServiceClient()

    name = client.processor_path(project_id, location, processor_id)

    with open(file_path, "rb") as image:
        image_content = image.read()

    raw_document = documentai.RawDocument(content=image_content, mime_type="application/pdf")

    request = documentai.ProcessRequest(name=name, raw_document=raw_document)

    result = client.process_document(request=request)
    document = result.document

    normalized_expense = {
        "vendor_name": None,
        "total_amount": None,
        "currency": None,
        "transaction_date": None,
        "line_items": []
    }

    # Extract top-level entities
    for entity in document.entities:
        if entity.type_ == "supplier_name" and entity.mention_text:
            normalized_expense["vendor_name"] = entity.mention_text
        elif entity.type_ == "total_amount" and entity.mention_text:
            try:
                normalized_expense["total_amount"] = float(entity.mention_text)
                # Google Document AI often provides currency in a separate entity or as part of total_amount
                # Look for a separate currency entity if available, otherwise try to extract from total_amount text
                if entity.properties:
                    for prop in entity.properties:
                        if prop.type_ == "currency" and prop.mention_text:
                            normalized_expense["currency"] = prop.mention_text
                            break
                if not normalized_expense["currency"]:
                    # Basic attempt to extract currency symbol from total_amount text if not found in properties
                    if "$" in entity.mention_text:
                        normalized_expense["currency"] = "USD"
                    elif "€" in entity.mention_text:
                        normalized_expense["currency"] = "EUR"
                    elif "£" in entity.mention_text:
                        normalized_expense["currency"] = "GBP"
            except ValueError:
                pass # Skip if conversion fails
        elif entity.type_ == "transaction_date" and entity.mention_text:
            normalized_expense["transaction_date"] = entity.mention_text # Keep as string for simplicity

    # Extract line items
    line_item_entities = [e for e in document.entities if e.type_ == "line_item"]
    for line_item_entity in line_item_entities:
        item = {
            "description": None,
            "quantity": None,
            "unit_price": None,
            "total_price": None
        }
        for prop in line_item_entity.properties:
            if prop.type_ == "description" and prop.mention_text:
                item["description"] = prop.mention_text
            elif prop.type_ == "quantity" and prop.mention_text:
                try:
                    item["quantity"] = int(float(prop.mention_text)) # Quantity can sometimes be float, cast to int
                except ValueError:
                    pass
            elif prop.type_ == "unit_price" and prop.mention_text:
                try:
                    item["unit_price"] = float(prop.mention_text)
                except ValueError:
                    pass
            elif prop.type_ == "line_item_amount" and prop.mention_text: # Common for line item total
                try:
                    item["total_price"] = float(prop.mention_text)
                except ValueError:
                    pass
        if item["description"] or item["total_price"]: # Only add if at least some info is present
            normalized_expense["line_items"].append(item)

    return normalized_expense
